CREATE TABLE IF NOT EXISTS acl_user(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(80) NOT NULL UNIQUE,password VARCHAR(120) NOT NULL,real_name VARCHAR(80),email VARCHAR(160),phone VARCHAR(30),status INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS acl_role(id BIGINT PRIMARY KEY AUTO_INCREMENT,role_name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(180),status INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS acl_resource(id BIGINT PRIMARY KEY AUTO_INCREMENT,parent_id BIGINT DEFAULT 0,resource_name VARCHAR(80),code VARCHAR(160) NOT NULL UNIQUE,kind INT DEFAULT 3,url VARCHAR(180),sort_order INT DEFAULT 0,status INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS acl_member(left_id BIGINT NOT NULL,right_id BIGINT NOT NULL,PRIMARY KEY(left_id,right_id),FOREIGN KEY(left_id) REFERENCES acl_user(id) ON DELETE CASCADE,FOREIGN KEY(right_id) REFERENCES acl_role(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS acl_grant(left_id BIGINT NOT NULL,right_id BIGINT NOT NULL,PRIMARY KEY(left_id,right_id),FOREIGN KEY(left_id) REFERENCES acl_role(id) ON DELETE CASCADE,FOREIGN KEY(right_id) REFERENCES acl_resource(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS dept(deptno INT PRIMARY KEY AUTO_INCREMENT,dname VARCHAR(100) NOT NULL,loc VARCHAR(100),deleted TINYINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS emp(empno INT PRIMARY KEY AUTO_INCREMENT,ename VARCHAR(100) NOT NULL,job VARCHAR(100),mgr INT,hiredate DATE,sal DECIMAL(10,2),comm DECIMAL(10,2),deptno INT,deleted TINYINT NOT NULL DEFAULT 0,FOREIGN KEY(deptno) REFERENCES dept(deptno));
CREATE TABLE IF NOT EXISTS login_account(id BIGINT PRIMARY KEY AUTO_INCREMENT,login_name VARCHAR(80) NOT NULL UNIQUE,secret VARCHAR(120) NOT NULL,mailbox VARCHAR(160) NOT NULL UNIQUE,staff_id INT,state INT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES emp(empno) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS supplier(supplier_id INT PRIMARY KEY AUTO_INCREMENT,supplier_name VARCHAR(100) NOT NULL,contact_name VARCHAR(80),phone VARCHAR(30),address VARCHAR(255));
CREATE TABLE IF NOT EXISTS product(product_id INT PRIMARY KEY AUTO_INCREMENT,product_name VARCHAR(120) NOT NULL,category VARCHAR(80),unit_price DECIMAL(10,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS supplier_product(supplier_id INT NOT NULL,product_id INT NOT NULL,supply_price DECIMAL(10,2) DEFAULT 0,PRIMARY KEY(supplier_id,product_id),FOREIGN KEY(supplier_id) REFERENCES supplier(supplier_id),FOREIGN KEY(product_id) REFERENCES product(product_id));
CREATE TABLE IF NOT EXISTS customer(customer_id INT PRIMARY KEY AUTO_INCREMENT,customer_name VARCHAR(100) NOT NULL,phone VARCHAR(30),address VARCHAR(255));
CREATE TABLE IF NOT EXISTS purchase(purchase_id INT PRIMARY KEY AUTO_INCREMENT,customer_id INT NOT NULL,supplier_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL DEFAULT 1,unit_price DECIMAL(10,2) DEFAULT 0,purchased_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customer(customer_id),FOREIGN KEY(supplier_id,product_id) REFERENCES supplier_product(supplier_id,product_id));
CREATE TABLE IF NOT EXISTS product_service(service_id INT PRIMARY KEY AUTO_INCREMENT,purchase_id INT NOT NULL,service_type VARCHAR(80) NOT NULL,service_note VARCHAR(500),serviced_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(purchase_id) REFERENCES purchase(purchase_id));
CREATE TABLE IF NOT EXISTS console_product_item(item_id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id INT NOT NULL,supplier_id INT NOT NULL,serial_no VARCHAR(100) NOT NULL UNIQUE,purchase_id INT,FOREIGN KEY(product_id) REFERENCES product(product_id),FOREIGN KEY(supplier_id) REFERENCES supplier(supplier_id),FOREIGN KEY(purchase_id) REFERENCES purchase(purchase_id));
CREATE TABLE IF NOT EXISTS mp_student(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,age INT,email VARCHAR(160),major VARCHAR(80),score DOUBLE,version INT DEFAULT 0 NOT NULL,deleted INT DEFAULT 0 NOT NULL,create_time TIMESTAMP,update_time TIMESTAMP);
